    thr={(r,c) for r in range(H) for c in range(W) if g[r][c]==3}
    par={}
    q=deque()
    for s in twos:
        par[(s[0],s[1])]=None
        q.append((s[0],s[1]))
    end=None
    while q:
        r,c=q.popleft()
        if (r,c) in thr: end=(r,c); break
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
