            if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg:
                par[(nr,nc)]=(r,c); q.append((nr,nc))
    P=[]; cur=end
    while True:
        P.append(cur); prev=par[cur]
        if prev in twos: break
        cur=prev
    out=[row[:] for row in g]
    for r,c in P:
        if out[r][c] not in (2,3): out[r][c]=3
    return out,P
